var createObject = function(keysArr, valuesArr) {
    const obj = {};
    for (let i = 0; i < keysArr.length; i++) {
        const key = String(keysArr[i]);
        if (!(key in obj)) {
            obj[key] = valuesArr[i];
        }
    }
    return obj;
};

function createObject(keysArr: any[], valuesArr: any[]): Record<string, any> {
    const obj: Record<string, any> = {};
    for (let i = 0; i < keysArr.length; i++) {
        const key = String(keysArr[i]);
        if (!(key in obj)) {
            obj[key] = valuesArr[i];
        }
    }
    return obj;
}
